#!/bin/sh
# Name: Sidle
# Author: _hzw
# Icon: data:image/png;base64,
# DontUseFBInk

# One tap from the home library into the picker. bin/sidle.sh holds the launch
# logging and the binary's own staged swap.
#
# The body is hand-edited. The `# Icon:` line above is generated by
# device/make-tile.sh from assets/cover.svg.

# A second picker over a running one leaves the framework SIGSTOP'd and the
# screen frozen.
#
# `pidof sidle` asks whether the name is taken, and any long-lived process
# started from that binary answers to it. The reading-log archiver runs from a
# file of its own for this reason.
if pidof sidle >/dev/null 2>&1; then
    exit 0
fi

# `peekHistoryView` names the view the tap came from. A `documents/` scriptlet
# is registered without a `lipcId`, and the app manager's fallback on exit is
# the home screen whichever tile was tapped.
#
# `SIDLE_ORIGIN_VIEW` crosses into bin/sidle.sh through the environment, which
# is the last thing this tile controls. The URI stored beside the view name on
# the stack lags a transition behind; the launcher builds its own from the name.
SIDLE_ORIGIN_VIEW=$(lipc-get-prop com.lab126.appmgrd peekHistoryView 2>/dev/null)
export SIDLE_ORIGIN_VIEW

# This tile execs bin/sidle.sh, one level above the file replaced here. `sh`
# reads a script by offset, and FAT keeps no inode alive under a replacement.
if [ -f /mnt/us/extensions/sidle/bin/sidle.sh.new ]; then
    mv -f /mnt/us/extensions/sidle/bin/sidle.sh.new /mnt/us/extensions/sidle/bin/sidle.sh
fi

exec /mnt/us/extensions/sidle/bin/sidle.sh
